<?php declare(strict_types=1);require __DIR__.'/bootstrap.php';use Phessage\OneComm\CatalogClient;use Phessage\OneComm\Plugin;$assert=fn($v,$m)=>$v?:throw new RuntimeException($m);
$GLOBALS['remote']=['response'=>['code'=>200],'body'=>'{"data":[{"name":"<Pack>","description":"Trail & camp","price":{"amount":"9.00","currency":"USD"}}]}'];$client=new CatalogClient('https://sandbox.test','pk_test_demo');$items=$client->products(999);$assert(count($items)===1,'catalog failed');$assert(str_ends_with($GLOBALS['last_request'][0],'/v1/headless/products?limit=100'),'route/limit failed');$assert($GLOBALS['last_request'][1]['redirection']===0,'redirects must be disabled');$assert($GLOBALS['last_request'][1]['headers']['x-publishable-key']==='pk_test_demo','key missing');
$GLOBALS['options']=['onecomm_api_url'=>'https://sandbox.test','onecomm_publishable_key'=>'pk_test_demo'];$html=Plugin::render(12);$assert(str_contains($html,'&lt;Pack&gt;'),'name not escaped');$assert(str_contains($html,'Trail &amp; camp'),'description not escaped');$assert(!str_contains($html,'<Pack>'),'unsafe output');$assert((new CatalogClient('https://sandbox.test','secret'))->products()===[],'confidential key accepted');echo "4 test groups passed\n";
